/** One arena's presentation data. */
export interface ArenaPresentation {
  /** The original mission. */
  readonly mission: string;
  /** The original side (1 red, 2 blue) whose X1-Alpha stands on the map's spawn 0: 1 on every arena. */
  readonly team0Side: 1 | 2;
  /** Column of reticles.png (16 px each). */
  readonly reticle: number;
  /** The type-35 record's contacts: shown bits (0 rim arrow, 1 map ring, 2 radar blip), palette index, m. */
  readonly contacts: readonly {
    readonly shown: number;
    readonly colour: number;
    readonly x: number;
    readonly y: number;
  }[];
  /**
   * Placed actors with a marker that Metropolis has no entity for (the outposts'
   * consoles); `record` names their scenery placement (arenaScenery.generated.ts).
   */
  readonly staticMarkers: readonly {
    readonly record: string;
    readonly marker: number;
    readonly x: number;
    readonly y: number;
  }[];
  /** The outposts' corner posts: [side 1's, side 2's] marker once claimed. */
  readonly claimMarkers: readonly {
    readonly record: string;
    readonly x: number;
    readonly y: number;
    readonly markers: P;
  }[];
  /**
   * By Cobj, the 3DBB box the map screen's arrow is built on, one per frame (box 0
   * of the actor's current frame, pause_map_draw_actor 0x0045180d; one entry where
   * every frame's is alike): centre x and z, half x and z, metres in the model's
   * own frame.
   */
  readonly boxes: Readonly<Record<number, readonly (readonly [number, number, number, number])[]>>;
  /**
   * The entities' arrow boxes (pause_map_draw_actor 0x004516e0): box 0 of the
   * actor's model by frame (one where all are alike) and its reach `radius_68`
   * (the box's +0x0c << 4, 0x004297e0), [centre x, centre z, half x, half z,
   * reach] metres. A turret's model is its gun, the Dreadnought's its hull,
   * the captain's by level. The X1-Alphas' are the view's shape block
   * (player_transform_shape 0x00441cf0) on the legs: [the walker's (frame 0,
   * progress 0), the hover's (frame 359, 0x10000)]. Absent on a map with no
   * original.
   */
  readonly unitBoxes?: {
    readonly avatar: readonly [ReachBox, ReachBox];
    readonly tank: readonly ReachBox[];
    readonly jet: readonly ReachBox[];
    readonly fortress: readonly ReachBox[];
    readonly dreadnought: readonly ReachBox[];
    readonly turret: readonly ReachBox[];
    readonly neutralTurret: readonly (readonly ReachBox[])[];
    readonly captain: readonly {
      readonly levels: readonly number[];
      readonly box: readonly ReachBox[];
    }[];
  };
}

/** [centre x, centre z, half x, half z, reach], metres. */
export type ReachBox = readonly [number, number, number, number, number];

